import priceableItems from './priceable-items.json';

// specs/025-rune-purchase-import (research R5, contracts/rune-items-data.md): a purchase line's item is
// recognized only by its exact name among the resources the app prices — the runes and the resources
// of src/data/hdv-items.json, never an equipment. The index is generated by scripts/build-rune-items.mjs.
// specs/045-restore-production-worker: `names` gives each item's official name, shown in place of a misread one.
const { items: index, names } = priceableItems as { items: Record<string, string | null>; names: Record<string, string> };
const knownIds = new Set(Object.values(index).filter((id): id is string => id !== null));

// Same rule as normalizeItemName in src/domain/forgemagie.ts, duplicated like worker/src/outlier.ts:
// the site and the Worker share no code. Accents are kept.
export function normalizeItemName(name: string): string {
  return name.toLowerCase().replace(/\s+/g, ' ').trim();
}

// specs/038: a name the capture's reading got slightly wrong is recovered when one item only can be meant.
// Read without its accents...
const withoutAccents = (name: string) => name.normalize('NFD').replace(/\p{M}/gu, '');
const accentIndex = new Map<string, string | null>();
for (const [name, itemId] of Object.entries(index)) {
  const key = withoutAccents(name);
  accentIndex.set(key, accentIndex.has(key) && accentIndex.get(key) !== itemId ? null : itemId);
}
// ...or with the frame of the game's window read as a character before or after the name.
const OPENING_BRACKET = new Set('[({|!1IlLEC');
const CLOSING_BRACKET = new Set('])}|!1IlJj');

function byNameOrAccents(name: string): string | undefined {
  const key = normalizeItemName(name);
  const exact = Object.hasOwn(index, key) ? index[key] : null;
  return exact ?? accentIndex.get(withoutAccents(key)) ?? undefined;
}

function recoverItem(name: string): string | undefined {
  const accents = accentIndex.get(withoutAccents(normalizeItemName(name)));
  if (accents) return accents;
  const read = name.trim();
  const opening = OPENING_BRACKET.has(read.charAt(0));
  const closing = CLOSING_BRACKET.has(read.charAt(read.length - 1));
  const variants = [opening && read.slice(1), closing && read.slice(0, -1), opening && closing && read.slice(1, -1)];
  const found = new Set(variants.flatMap((variant) => (variant ? byNameOrAccents(variant) ?? [] : [])));
  return found.size === 1 ? [...found][0] : undefined;
}

// `name` is set only when the item was recovered from a misread name: its official name.
export type ItemLookup = { status: 'found'; itemId: string; name?: string } | { status: 'unknown-item' } | { status: 'ambiguous-item' };

export function lookupItem(name: string): ItemLookup {
  const key = normalizeItemName(name);
  if (Object.hasOwn(index, key)) {
    const itemId = index[key];
    return itemId === null ? { status: 'ambiguous-item' } : { status: 'found', itemId };
  }
  const itemId = recoverItem(name);
  return itemId ? { status: 'found', itemId, name: names[itemId] } : { status: 'unknown-item' };
}

export function isPriceableItemId(itemId: string): boolean {
  return knownIds.has(itemId);
}
